#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string regex;
    int q;
    cin >> regex >> q;
    // Atoms: a letter, '.', or a group's contents, each with whether it carries '*'.
    vector<pair<string, bool>> atoms;
    for (size_t i = 0; i < regex.size();) {
        string pat;
        if (regex[i] == '(') {
            size_t end = regex.find(')', i);
            pat = regex.substr(i + 1, end - i - 1);
            i = end + 1;
        } else {
            pat = regex.substr(i, 1);
            i++;
        }
        bool star = i < regex.size() && regex[i] == '*';
        if (star) i++;
        atoms.push_back({pat, star});
    }
    string out;
    while (q--) {
        string word;
        cin >> word;
        if (word == "-") word = "";
        int m = word.size();
        // dp[e]: the first e characters match the atoms processed so far.
        vector<char> dp(m + 1, 0);
        dp[0] = 1;
        for (auto &[pat, star] : atoms) {
            if (pat.empty()) continue;  // an empty ()* only matches the empty string
            int len = pat.size();
            vector<char> nxt = star ? dp : vector<char>(m + 1, 0);
            // With '*', nxt[end - len] may already include repetitions of this atom.
            for (int end = len; end <= m; end++) {
                if (!(star ? nxt[end - len] : dp[end - len])) continue;
                bool good = true;
                for (int off = 0; off < len && good; off++) good = pat[off] == '.' || pat[off] == word[end - len + off];
                if (good) nxt[end] = 1;
            }
            dp = move(nxt);
        }
        out += dp[m] ? "YES\n" : "NO\n";
    }
    cout << out;
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String regex = next();
        int q = nextInt();
        // Atoms: a letter, '.', or a group's contents, each with whether it carries '*'.
        List<String> pats = new ArrayList<>();
        List<Boolean> stars = new ArrayList<>();
        for (int i = 0; i < regex.length();) {
            String pat;
            if (regex.charAt(i) == '(') {
                int end = regex.indexOf(')', i);
                pat = regex.substring(i + 1, end);
                i = end + 1;
            } else {
                pat = regex.substring(i, i + 1);
                i++;
            }
            boolean star = i < regex.length() && regex.charAt(i) == '*';
            if (star) i++;
            pats.add(pat);
            stars.add(star);
        }
        StringBuilder out = new StringBuilder();
        for (int w = 0; w < q; w++) {
            String word = next();
            if (word.equals("-")) word = "";
            int m = word.length();
            // dp[e]: the first e characters match the atoms processed so far.
            boolean[] dp = new boolean[m + 1];
            dp[0] = true;
            for (int t = 0; t < pats.size(); t++) {
                String pat = pats.get(t);
                if (pat.isEmpty()) continue;  // an empty ()* only matches the empty string
                boolean star = stars.get(t);
                int plen = pat.length();
                boolean[] nxt = star ? dp.clone() : new boolean[m + 1];
                // With '*', nxt[end - plen] may already include repetitions of this atom.
                for (int end = plen; end <= m; end++) {
                    if (!(star ? nxt[end - plen] : dp[end - plen])) continue;
                    boolean good = true;
                    for (int off = 0; off < plen && good; off++) {
                        char p = pat.charAt(off);
                        good = p == '.' || p == word.charAt(end - plen + off);
                    }
                    if (good) nxt[end] = true;
                }
                dp = nxt;
            }
            out.append(dp[m] ? "YES" : "NO").append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strings"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	regex := string(nextToken())
	q := int(nextInt())
	// Atoms: a letter, '.', or a group's contents, each with whether it carries '*'.
	type atom struct {
		pat  string
		star bool
	}
	var atoms []atom
	for i := 0; i < len(regex); {
		var pat string
		if regex[i] == '(' {
			end := i + strings.IndexByte(regex[i:], ')')
			pat = regex[i+1 : end]
			i = end + 1
		} else {
			pat = regex[i : i+1]
			i++
		}
		star := i < len(regex) && regex[i] == '*'
		if star {
			i++
		}
		atoms = append(atoms, atom{pat, star})
	}
	var out []byte
	for ; q > 0; q-- {
		word := nextToken()
		if string(word) == "-" {
			word = nil
		}
		m := len(word)
		// dp[e]: the first e characters match the atoms processed so far.
		dp := make([]bool, m+1)
		dp[0] = true
		for _, a := range atoms {
			if a.pat == "" {
				continue // an empty ()* only matches the empty string
			}
			plen := len(a.pat)
			var nxt []bool
			if a.star {
				nxt = slices.Clone(dp)
			} else {
				nxt = make([]bool, m+1)
			}
			// With '*', nxt[end - plen] may already include repetitions of this atom.
			for end := plen; end <= m; end++ {
				if a.star && !nxt[end-plen] || !a.star && !dp[end-plen] {
					continue
				}
				good := true
				for off := 0; off < plen && good; off++ {
					good = a.pat[off] == '.' || a.pat[off] == word[end-plen+off]
				}
				if good {
					nxt[end] = true
				}
			}
			dp = nxt
		}
		if dp[m] {
			out = append(out, "YES\n"...)
		} else {
			out = append(out, "NO\n"...)
		}
	}
	os.Stdout.Write(out)
}
